using System;using System.Linq;using System.Collections.Generic;using UnityEditor;using UnityEngine;using Object=UnityEngine.Object;
// Rebuild from the polished source in the fitted model's original coordinate frame.
public static class FALFullReloadConversion {
const string Folder="Assets/Game/Animations/Weapons/Reloads/SharedConversions/FAL/";
const string Source="Assets/Game/Animations/Weapons/Scaled/legacy-fal/";
static Transform Find(GameObject root,string name)=>root.GetComponentsInChildren<Transform>(true).First(t=>t.name==name);
sealed class Rig:IDisposable{public GameObject root;public Transform gun,mount;Transform[] nodes;(Vector3 p,Quaternion q,Vector3 s)[] rest;public Rig(SoldierWeaponView view,bool source){root=Object.Instantiate(view.sharedFirstPersonRig);foreach(var a in root.GetComponentsInChildren<Animator>(true))a.enabled=false;mount=root.transform.Find(source?"ViewMotion/WeaponMotion":view.sharedWeaponMountPath);gun=source?new GameObject("SourceWeapon").transform:Object.Instantiate(view,mount,false).transform;gun.SetParent(mount,false);gun.name="SourceWeapon";gun.SetLocalPositionAndRotation(source?new Vector3(.14149828f,1.4094143f,.26234362f):view.mountPosition,source?Quaternion.identity:view.mountRotation);gun.localScale=source?Vector3.one*.93863153f:view.mountScale;nodes=root.GetComponentsInChildren<Transform>(true);rest=nodes.Select(t=>(t.localPosition,t.localRotation,t.localScale)).ToArray();}public void Reset(){for(int i=0;i<nodes.Length;i++){nodes[i].SetLocalPositionAndRotation(rest[i].p,rest[i].q);nodes[i].localScale=rest[i].s;}}public void Dispose()=>Object.DestroyImmediate(root);}
static void Solve(Transform u,Transform f,Transform h,Vector3 goal,Quaternion q,Vector3 hint){var p=u.position;float a=Vector3.Distance(p,f.position),b=Vector3.Distance(f.position,h.position);var d=goal-p;float length=Mathf.Clamp(d.magnitude,Mathf.Abs(a-b)+.0001f,a+b-.0001f);var axis=d.normalized;var bend=Vector3.ProjectOnPlane(hint-p,axis).normalized;if(bend.sqrMagnitude<.01f)bend=Vector3.ProjectOnPlane(Vector3.up,axis).normalized;float x=(a*a-b*b+length*length)/(2*length);var elbow=p+axis*x+bend*Mathf.Sqrt(Mathf.Max(0,a*a-x*x));u.rotation=Quaternion.FromToRotation(f.position-p,elbow-p)*u.rotation;f.rotation=Quaternion.FromToRotation(h.position-f.position,p+axis*length-f.position)*f.rotation;h.rotation=q;}
[MenuItem("Tools/Weapons/Rebuild Polygon FAL Full Reload")]
public static void Rebuild()=>Run();
public static object Run(){if(EditorApplication.isPlayingOrWillChangePlaymode)throw new InvalidOperationException("Exit Play Mode before conversion.");var cat=AssetDatabase.LoadAssetAtPath<WeaponCatalog>("Assets/Game/Definitions/Weapons/Catalogs/WeaponCatalog.asset");var e=cat.entries.Single(e=>e.weapon.displayName=="FN FAL Para");var v=e.firstPersonPrefab;var idle=WeaponAnimationSource.State(v.animationOverride,"Base Layer","Idle");var sourceIdle=AssetDatabase.LoadAssetAtPath<AnimationClip>(Source+"Gameplay_Idle_UE4.anim");var sourceReload=AssetDatabase.LoadAssetAtPath<AnimationClip>(Source+"Gameplay_Reload_UE4.anim");using var old=new Rig(v,true);using var target=new Rig(v,false);using var tacticalReference=new Rig(v,false);var tacticalClip=WeaponAnimationSource.State(v.ReloadAnimation(false),"Base Layer","Reload");var referenceUpper=new[]{Find(tacticalReference.root,"upperarm_l"),Find(tacticalReference.root,"upperarm_r")};var referenceFore=new[]{Find(tacticalReference.root,"lowerarm_l"),Find(tacticalReference.root,"lowerarm_r")};sourceIdle.SampleAnimation(old.root,0);idle.SampleAnimation(target.root,0);var sourceP=old.gun.position;var sourceQ=old.gun.rotation;var gunP=target.gun.position;var gunQ=target.gun.rotation;var local=(target.gun.localPosition,target.gun.localRotation,target.gun.localScale);var fit=target.gun.Find("Model/Fit");if(!fit)throw new Exception("Missing FAL fitted source frame");var hands=new[]{Find(target.root,"hand_l"),Find(target.root,"hand_r")};var sourceHands=new[]{Find(old.root,"hand_l"),Find(old.root,"hand_r")};var elbows=new[]{Find(target.root,"lowerarm_l"),Find(target.root,"lowerarm_r")};var idleHands=hands.Select(h=>h.position).ToArray();var idleQ=hands.Select(h=>h.rotation).ToArray();var idleElbows=elbows.Select(h=>h.position).ToArray();var fingers=Find(target.root,"SourceArms").GetComponentsInChildren<Transform>(true).Where(t=>new[]{"thumb_","index_","middle_","ring_","pinky_"}.Any(t.name.StartsWith)).ToArray();var idleFingers=fingers.Select(t=>t.localRotation).ToArray();var sourceFingers=fingers.Select(t=>Find(old.root,t.name)).ToArray();var nodes=Find(target.root,"root").GetComponentsInChildren<Transform>(true).Where(t=>t!=target.gun&&!t.IsChildOf(target.gun)).Concat(new[]{target.root.transform.Find("ViewMotion"),target.root.transform.Find("ViewMotion/WeaponMotion"),Find(target.root,"SourceArms"),target.gun}).Distinct().ToArray();var rest=nodes.Select(t=>(t.localPosition,t.localRotation,t.localScale)).ToArray();var tracks=nodes.Select(t=>new TpsPartsAdapter.PoseTrack{source=t,path=AnimationUtility.CalculateTransformPath(t,target.root.transform)}).ToArray();var parts=AssetDatabase.LoadAssetAtPath<AnimationClip>(Folder+"FullMechanisms.anim");int count=Mathf.CeilToInt(sourceReload.length*120);var times=new float[count+1];float handError=0,holdError=0;
for(int i=0;i<=count;i++){float t=sourceReload.length*i/count;times[i]=t;old.Reset();sourceIdle.SampleAnimation(old.root,0);sourceReload.SampleAnimation(old.root,t);tacticalReference.Reset();idle.SampleAnimation(tacticalReference.root,0);tacticalClip.SampleAnimation(tacticalReference.root,tacticalClip.length*Mathf.Min(t/sourceReload.length,.60f));target.Reset();idle.SampleAnimation(target.root,0);float blend=Mathf.SmoothStep(0,1,t/.23f)*Mathf.SmoothStep(0,1,(sourceReload.length-.12f-t)/.30f);var p=gunP+old.gun.position-sourceP;var q=old.gun.rotation*Quaternion.Inverse(sourceQ)*gunQ;var desired=Matrix4x4.TRS(Vector3.Lerp(gunP,p,blend),Quaternion.Slerp(gunQ,q,blend),target.gun.lossyScale);var frame=desired*Matrix4x4.TRS(local.localPosition,local.localRotation,local.localScale).inverse;target.mount.SetPositionAndRotation(frame.GetColumn(3),frame.rotation);target.gun.SetLocalPositionAndRotation(local.localPosition,local.localRotation);target.gun.localScale=local.localScale;parts.SampleAnimation(target.root,t);
for(int side=0;side<2;side++){var goal=fit.TransformPoint(old.gun.InverseTransformPoint(sourceHands[side].position));var rotation=fit.rotation*Quaternion.Inverse(old.gun.rotation)*sourceHands[side].rotation;string s=side==0?"l":"r";var upper=Find(target.root,"upperarm_"+s);
// Retain the accepted wrist target; take only the bend-plane preference from the tactical reload.
var referenceBend=referenceUpper[side].parent.InverseTransformDirection(referenceFore[side].position-referenceUpper[side].position).normalized;var restBend=upper.parent.InverseTransformDirection(idleElbows[side]-upper.position).normalized;
// Finish in the accepted idle bend plane before the hand reaches the foregrip. Interpolate directions, not world-space pole positions.
float settle=Mathf.SmoothStep(0,1,Mathf.InverseLerp(.70f,.88f,t/sourceReload.length));var bend=Vector3.Slerp(referenceBend,restBend,settle).normalized;var pole=upper.position+upper.parent.TransformDirection(bend)*Vector3.Distance(upper.position,elbows[side].position);Solve(Find(target.root,"upperarm_"+s),elbows[side],hands[side],Vector3.Lerp(idleHands[side],goal,blend),Quaternion.Slerp(idleQ[side],rotation,blend),Vector3.Lerp(idleElbows[side],pole,blend));if(blend>.9999f)handError=Mathf.Max(handError,Vector3.Distance(hands[side].position,goal));}
for(int k=0;k<fingers.Length;k++)fingers[k].localRotation=Quaternion.Slerp(idleFingers[k],sourceFingers[k].localRotation,blend);if(blend<=.000001f)for(int k=0;k<nodes.Length;k++){nodes[k].SetLocalPositionAndRotation(rest[k].localPosition,rest[k].localRotation);nodes[k].localScale=rest[k].localScale;}if(t>=sourceReload.length-.1f)for(int k=0;k<nodes.Length;k++)holdError=Mathf.Max(holdError,Vector3.Distance(nodes[k].localPosition,rest[k].localPosition));foreach(var track in tracks)track.Sample();}
var output=new AnimationClip{frameRate=120};foreach(var track in tracks)TpsPartsAdapter.Write(output,track,times);output=WeaponReloadBuilder.Save(output,Folder+"FullFPS.anim");var combined=Object.Instantiate(output);foreach(var b in AnimationUtility.GetCurveBindings(parts))AnimationUtility.SetEditorCurve(combined,b,AnimationUtility.GetEditorCurve(parts,b));var combinedIdle=Object.Instantiate(idle);var idleParts=AssetDatabase.LoadAssetAtPath<AnimationClip>(Folder+"IdleMechanisms.anim");foreach(var b in AnimationUtility.GetCurveBindings(idleParts))AnimationUtility.SetEditorCurve(combinedIdle,b,AnimationUtility.GetEditorCurve(idleParts,b));var proof=ScriptableObject.CreateInstance<WeaponAnimationConversionProof>();try{proof.originalProportions=true;proof.source=proof.converted=e;proof.idle=combinedIdle;proof.reload=combined;proof.thirdPersonSourceController=e.weapon.thirdPerson;proof.thirdPersonSourceParts=e.weapon.fullReload.thirdPersonParts;TpsAnimationAdapter.BuildReload(proof,Folder+"FullBody");AssetDatabase.DeleteAsset(Folder+"FullBody/ReloadParts.anim");}finally{Object.DestroyImmediate(proof);Object.DestroyImmediate(combined);Object.DestroyImmediate(combinedIdle);}
// A tactical reload does not operate the charging handle, including its folding tab.
int frozen=0;foreach(string suffix in new[]{"","TPS"}){var tactical=AssetDatabase.LoadAssetAtPath<AnimationClip>(Folder+"TacticalMechanisms"+suffix+".anim");var restClip=AssetDatabase.LoadAssetAtPath<AnimationClip>(Folder+"IdleMechanisms"+suffix+".anim");foreach(var b in AnimationUtility.GetCurveBindings(tactical).Where(b=>b.path.Contains("/ChargingHandle"))){var curve=AnimationUtility.GetEditorCurve(restClip,b);if(curve==null)throw new Exception("Missing handle rest "+b.path);AnimationUtility.SetEditorCurve(tactical,b,AnimationCurve.Constant(0,tactical.length,curve.Evaluate(0)));frozen++;}EditorUtility.SetDirty(tactical);}AssetDatabase.SaveAssets();return new{weapon=e.weapon.displayName,duration=sourceReload.length,maxPreservedHandContactErrorMeters=handError,endHoldErrorMeters=holdError,tacticalHandleChannelsFrozen=frozen,fullMechanismsUnchanged=true};}}
